// ============================================================================
// HELPER: Safely parse JSON strings (when HTTP node returns raw text)
// ============================================================================
function parseBody(data) {
  if (typeof data === 'string') {
    try {
      return JSON.parse(data);
    } catch {
      return data;
    }
  }
  return data;
}

const fmt = (ms) =>
  new Date(ms).toLocaleString('en-US', {
    timeZone: 'America/Chicago', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit',
  });

// ============================================================================
// SERVICE DEFINITIONS & HEALTH VALIDATION RULES
// ============================================================================
const checks = [
  {
    key: 'grafana',
    name: 'Grafana (CT405)',
    node: 'Grafana health',
    validate: (r) => r.statusCode === 200 && parseBody(r.data)?.database === 'ok',
  },
  {
    key: 'victoriametrics',
    name: 'VictoriaMetrics (CT405)',
    node: 'VictoriaMetrics health',
    validate: (r) => r.statusCode === 200 && String(r.data).trim() === 'OK',
  },
  {
    key: 'loki',
    name: 'Loki (CT405)',
    node: 'Loki query',
    validate: (r) => {
      const body = parseBody(r.data);
      return r.statusCode === 200 && (body?.status === 'success' || Array.isArray(body?.data));
    },
  },
  {
    key: 'gotify',
    name: 'Gotify (CT203)',
    node: 'Gotify health',
    validate: (r) => {
      const body = parseBody(r.data);
      return r.statusCode === 200 && body?.health === 'green' && body?.database === 'green';
    },
  },
];

// ============================================================================
// STATE: which services we already alerted about, kept between scheduled runs.
// { down: { grafana: { since: <ms>, lastSent: <ms> }, ... } }
// (n8n only saves static data on scheduled/active runs, not manual test runs.)
// ============================================================================
const state = $getWorkflowStaticData('global');
state.down = state.down || {};
const REMIND_MS = 6 * 60 * 60 * 1000; // reminder while still down: every 6 h

// ============================================================================
// 1. WHICH PASS IS THIS? ($runIndex: 0 = first probe, 1 = re-check after Wait)
// ============================================================================
const isSecondRun = $runIndex >= 1;
let failedProbe1 = {};
if (isSecondRun) {
  try {
    failedProbe1 = $('Probe failure').first(0, 0).json.failedProbe1 || {};
  } catch {
    failedProbe1 = {};
  }
}

// ============================================================================
// 2. EVALUATE CURRENT HEALTH CHECKS
// ============================================================================
const healthy = {};
const currentFailures = {};
for (const c of checks) {
  let r = {};
  try {
    // .last() reads the latest loop execution of each HTTP node
    r = $(c.node).last().json || {};
  } catch {
    r = { error: { message: 'no output' } };
  }
  const ok = !r.error && c.validate(r);
  healthy[c.key] = ok;
  if (!ok) {
    currentFailures[c.key] = r.error
      ? r.error.message || r.error.code || 'request failed'
      : `HTTP ${r.statusCode}`;
  }
}

// First pass and something failed: wait 3 min and re-check before deciding anything.
if (!isSecondRun && Object.keys(currentFailures).length > 0) {
  return [{ json: { runPass: 1, shouldWait: true, anyDown: true, shouldNotify: false, failedProbe1: currentFailures } }];
}

// ============================================================================
// 3. FINAL PASS: compare confirmed outages with the saved state
// ============================================================================
// Confirmed = failed on both passes (on a clean first pass there are none).
const confirmed = {};
for (const key of Object.keys(currentFailures)) {
  if (failedProbe1[key]) confirmed[key] = currentFailures[key];
}

const now = Date.now();
const newlyDown = [];
const stillDown = [];
const recovered = [];

for (const c of checks) {
  const was = state.down[c.key];
  if (confirmed[c.key]) {
    if (!was) {
      state.down[c.key] = { since: now, lastSent: now };
      newlyDown.push(c);
    } else if (now - was.lastSent >= REMIND_MS) {
      was.lastSent = now;
      stillDown.push(c);
    }
  } else if (was && healthy[c.key]) {
    delete state.down[c.key];
    recovered.push({ ...c, since: was.since });
  }
}

const shouldNotify = newlyDown.length + stillDown.length + recovered.length > 0;
const names = (list) => list.map((c) => c.name).join(', ');

const title = newlyDown.length
  ? `[DOWN] ${names(newlyDown)}`
  : stillDown.length
    ? `[STILL DOWN] ${names(stillDown)}`
    : `[RESOLVED] ${names(recovered)}`;

const lines = [
  ...newlyDown.map((c) => `• ${c.name}: ${confirmed[c.key]}`),
  ...stillDown.map((c) => `• ${c.name} still down since ${fmt(state.down[c.key].since)}: ${confirmed[c.key]}`),
  ...recovered.map((c) => `✓ ${c.name} is back (down since ${fmt(c.since)})`),
];
if (newlyDown.length || stillDown.length) {
  lines.push('', 'While this lasts, Grafana alerts may not be delivered.');
  if (!healthy.grafana || !healthy.victoriametrics || !healthy.loki) {
    lines.push("Check CT405: ssh evox2 'pct exec 405 -- docker ps -a' (then docker compose logs <svc> in /root/Homelab-ops/infrastructure/observability-lxc).");
  }
  if (!healthy.gotify) {
    lines.push("Check CT203: ssh peladn 'pct exec 203 -- docker ps -a' (gotify) and the NPM proxy for notifications.");
  }
}
lines.push('', '(from the n8n watchdog on the RPi4)');

return [{
  json: {
    runPass: $runIndex + 1,
    shouldWait: false,
    anyDown: Object.keys(confirmed).length > 0,
    shouldNotify,
    gotifyUp: healthy.gotify,
    title,
    message: lines.join('\n'),
    priority: newlyDown.length || stillDown.length ? 8 : 4,
    failedProbe1,
    down: Object.keys(state.down),
  },
}];
